import{_ as n,o as i,c as e,a5 as t}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"FR 3.5.4 — Thay bước duyệt Package bằng ghi nhận gói của Manager","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-4-approve-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-4-approve-media-package/spec.md"}'),h={name:"feature/media-package-campaign/3-5-4-approve-media-package/spec.md"};function c(g,a,r,o,l,p){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="fr-3-5-4-—-thay-buoc-duyet-package-bang-ghi-nhan-goi-cua-manager" tabindex="-1">FR 3.5.4 — Thay bước duyệt Package bằng ghi nhận gói của Manager <a class="header-anchor" href="#fr-3-5-4-—-thay-buoc-duyet-package-bang-ghi-nhan-goi-cua-manager" aria-label="Permalink to &quot;FR 3.5.4 — Thay bước duyệt Package bằng ghi nhận gói của Manager&quot;">​</a></h1><p>Cập nhật BA 2026-11-05. Bước duyệt Package hai phía trong spec cũ đã được thay thế bởi <a href="./../guest-sharing-manager-led/spec.html">hành trình Manager quản lý</a>.</p><h2 id="quy-tac-hien-hanh" tabindex="-1">Quy tắc hiện hành <a class="header-anchor" href="#quy-tac-hien-hanh" aria-label="Permalink to &quot;Quy tắc hiện hành&quot;">​</a></h2><ul><li>Manager chốt nội dung với Client bên ngoài và lưu gói workspace theo thỏa thuận.</li><li>Không yêu cầu Client chọn hoặc bấm duyệt gói trong hệ thống. Không chờ timestamp/version approval của Client để tạo Campaign/task.</li><li>Lưu gói đủ điều kiện tự tạo Campaign DRAFT và task lớn theo gói. Không có nút Manager xác nhận gói riêng sau bước lưu này.</li><li>Các lần lưu sau dùng cùng gói/Campaign và đồng bộ phần thay đổi trước triển khai.</li><li>Client được mời vào để xem gói đã ghi nhận và góp ý Campaign. Membership không phụ thuộc vào việc Client hoàn thành thao tác duyệt Package.</li><li>Manager có thể chuẩn bị gói/Campaign trước khi workspace có Client. Module nào cần Client để duyệt kết quả Task vẫn kiểm tra điều kiện riêng của module đó.</li><li>Thay điều kiện khóa theo Package APPROVED bằng thời điểm cố định bản triển khai và khóa sau triển khai theo spec mới.</li></ul><h2 id="tuong-thich-va-ui" tabindex="-1">Tương thích và UI <a class="header-anchor" href="#tuong-thich-va-ui" aria-label="Permalink to &quot;Tương thích và UI&quot;">​</a></h2><p>Lịch sử duyệt cũ là dữ liệu lịch sử cần giữ. Chuyển đổi trạng thái/field legacy được thiết kế riêng trước implementation, không suy approval mới cho Client. UI mới bỏ CTA/gate/checklist duyệt gói của Client và có vi/en, light/dark, loading/error/permission states tương ứng.</p><p>Tài liệu này thay hành vi FR cũ, chưa phải hợp đồng endpoint hoặc migration đã được triển khai.</p>',7)])])}const d=n(h,[["render",c]]);export{s as __pageData,d as default};
